    let env = WowLuaEnv::new().expect("bare Wrath Lua environment");
    let spec = SweepSpec {
        register: r#"{"client_line":"retail","entries":[]}"#,
        known_gaps: "[]",
        row_count: 0,
        register_env: "WOW_SIM_P342_RETAIL_CONTROL_REGISTER",
        out_env: "WOW_SIM_P342_RETAIL_CONTROL_OUT",
        later_registers: &[],
    };
